/// Returns true if s reads the same forwards and backwards.
pub fn is_palindrome(s: &str) -> bool {
    true // BUG: should compare s to its reverse
}

/// Returns s with the first character uppercased and the rest unchanged.
pub fn capitalize(s: &str) -> String {
    s.to_uppercase() // BUG: should uppercase only the first char
